namespace ws::http {

std::string StatusCodeToMessage(StatusCode code) {
    switch (code) {
        case StatusCode::F200:
            return "OK";
        case StatusCode::U404:
            return "Not Found";
        default:
            return "Unknown Status Code";
    }
}

int StatusCodeToInteger(StatusCode code) {
    switch (code) {
        case StatusCode::F200:
            return 200;
        case StatusCode::U404:
            return 404;
        default:
            return -1;
    }
}

std::ostream& operator<<(std::ostream& os, StatusCode code) {
    os << StatusCodeToMessage(code);
    return os;
}

std::string MethodToString(Method method) {
    switch (method) {
        case Method::GET:
            return "GET";
        case Method::POST:
            return "POST";
        default:
            return "Unknown Method";
    }
}

template<typename T>
T to_string(Method method) {
    return static_cast<T>(MethodToString(method));
}

Method StringToMethod(const std::string& str) {
    if (str == "GET") {
        return Method::GET;
    } else if (str == "POST") {
        return Method::POST;
    } else {
        throw std::invalid_argument("Unknown method");
    }
}

template<typename T>
T operator<<(std::ostream& os, Method method) {
    os << MethodToString(method);
    return static_cast<T>(os);
}

