        decoded += DecodeURLEncodedCharacter(c);
    }
    return decoded;
}

std::string HTMLPlaceholder(const std::string& param) {
    return "{{" + param + "}}";
}

void PutParamIntoHTML(std::string& html, const Parameters& params) {
    for (const auto& [key, value] : params) {
        std::string placeholder = HTMLPlaceholder(key);
        size_t pos = 0;
        while ((pos = html.find(placeholder, pos)) != std::string::npos) {
            html.replace(pos, placeholder.length(), value);
            pos += value.length();
        }
    }
}

